import{_ as e,o as l,c,ae as t}from"./chunks/framework.B3uLoxsb.js";const u=JSON.parse('{"title":"Source: docs/OPERATIONS.md","description":"","frontmatter":{},"headers":[],"relativePath":"pt/reference/source/operations.md","filePath":"pt/reference/source/operations.md","lastUpdated":1771052491000}'),i={name:"pt/reference/source/operations.md"};function s(a,o,d,r,p,n){return l(),c("div",null,[...o[0]||(o[0]=[t('<h1 id="source-docs-operations-md" tabindex="-1">Source: docs/OPERATIONS.md <a class="header-anchor" href="#source-docs-operations-md" aria-label="Permalink to &quot;Source: docs/OPERATIONS.md&quot;">​</a></h1><h1 id="operations-runbook" tabindex="-1">Operations Runbook <a class="header-anchor" href="#operations-runbook" aria-label="Permalink to &quot;Operations Runbook&quot;">​</a></h1><p>Use this runbook to maintain <code>codex-workflows</code>.</p><h2 id="unified-cli" tabindex="-1">Unified CLI <a class="header-anchor" href="#unified-cli" aria-label="Permalink to &quot;Unified CLI&quot;">​</a></h2><p>Primary entrypoint in this repository:</p><p><code>python scripts/codexwf.py &lt;command&gt;</code></p><p>Main commands:</p><ul><li><code>install</code></li><li><code>init</code></li><li><code>status</code></li><li><code>validate</code></li><li><code>docs-sync</code></li></ul><h2 id="distribution-quickstart" tabindex="-1">Distribution quickstart <a class="header-anchor" href="#distribution-quickstart" aria-label="Permalink to &quot;Distribution quickstart&quot;">​</a></h2><p>Primary installation channel (all-in-one):</p><p><code>npx @codex-workflow/cw</code></p><p>Core-only:</p><p><code>npx @codex-workflow/cw --core-only</code></p><p>Diagnostics:</p><p><code>npx @codex-workflow/cw doctor</code></p><p>Alternative repository-local install commands:</p><ul><li><code>python scripts/install_all_in_one.py</code></li><li><code>python scripts/codexwf.py install</code></li></ul><p>Bootstrap local project instructions (default codex-native profile):</p><p><code>python skills/codex-workflows/scripts/bootstrap_project_agent.py --project .</code></p><p>Composer wrapper (optional for PHP teams):</p><p><code>composer codex:install-all</code></p><p>Activation shortcuts:</p><ul><li><code>cw /&lt;workflow&gt; &lt;objective&gt;</code></li><li><code>codex-workflow /&lt;workflow&gt; &lt;objective&gt;</code></li><li><code>codex-workflows /&lt;workflow&gt; &lt;objective&gt;</code></li><li><code>cw /help</code></li><li><code>cw /examples</code></li></ul><p>Preview without changes:</p><p><code>npx @codex-workflow/cw --dry-run</code></p><h2 id="website-quickstart" tabindex="-1">Website quickstart <a class="header-anchor" href="#website-quickstart" aria-label="Permalink to &quot;Website quickstart&quot;">​</a></h2><p>Run the docs portal locally:</p><p><code>cd website &amp;&amp; npm install &amp;&amp; npm run docs:dev</code></p><p>Build production static output:</p><p><code>cd website &amp;&amp; npm run docs:build</code></p><p>Refresh mirrored technical docs:</p><p><code>python website/scripts/sync_reference_docs.py</code></p><h2 id="legacy-skill-ops-commands" tabindex="-1">Legacy skill-ops commands <a class="header-anchor" href="#legacy-skill-ops-commands" aria-label="Permalink to &quot;Legacy skill-ops commands&quot;">​</a></h2><p>Unified CLI:</p><p><code>python skills/codex-workflows/scripts/codex_workflows_ops.py &lt;command&gt;</code></p><p>Available commands:</p><ul><li><code>build-manifest</code></li><li><code>check-drift</code></li><li><code>check-workflows</code></li><li><code>check-codex-native</code></li><li><code>check-codex-assets</code></li><li><code>check-codex-rules</code></li><li><code>benchmark</code></li><li><code>bootstrap</code></li><li><code>sync-pack</code></li><li><code>release</code></li></ul><p><code>build-manifest</code> source resolution order:</p><ol><li><code>--source &lt;path&gt;</code> (if provided)</li><li><code>./.agent</code> from current working directory</li><li>fallback to <code>skills/codex-workflows/packs/antigravity-compat/.agent</code></li></ol><p>If fallback is used, the command prints a warning and still produces a valid manifest.</p><h2 id="typical-maintenance-cycle" tabindex="-1">Typical maintenance cycle <a class="header-anchor" href="#typical-maintenance-cycle" aria-label="Permalink to &quot;Typical maintenance cycle&quot;">​</a></h2><ol><li><p>Sync compatibility pack: <code>python skills/codex-workflows/scripts/sync_compat_pack.py --source &lt;path-to-.agent&gt;</code></p></li><li><p>Rebuild compatibility manifest: <code>python skills/codex-workflows/scripts/build_compat_manifest.py --source &lt;path-to-.agent&gt; --pack skills/codex-workflows/packs/antigravity-compat/.agent --template-full skills/codex-workflows/templates/.agent --output skills/codex-workflows/compat/manifest.json</code></p></li></ol><p>Alternative using unified ops command with auto source resolution: <code>python skills/codex-workflows/scripts/codex_workflows_ops.py build-manifest</code></p><ol start="3"><li>Run consistency checks:</li></ol><ul><li><code>python skills/codex-workflows/scripts/check_compat_drift.py --manifest skills/codex-workflows/compat/manifest.json --pack skills/codex-workflows/packs/antigravity-compat/.agent --template-full skills/codex-workflows/templates/.agent</code></li><li><code>python skills/codex-workflows/scripts/check_workflow_parity.py --references skills/codex-workflows/references/workflows --native skills/codex-workflows/templates/codex-native/.agent/workflows --template skills/codex-workflows/templates/.agent/workflows --pack skills/codex-workflows/packs/antigravity-compat/.agent/workflows</code></li><li><code>python skills/codex-workflows/scripts/check_codex_native_quality.py --native skills/codex-workflows/templates/codex-native/.agent/workflows --compat skills/codex-workflows/packs/antigravity-compat/.agent/workflows --max-similarity 0.35</code></li><li><code>python skills/codex-workflows/scripts/check_codex_native_assets.py --native-root skills/codex-workflows/templates/codex-native/.agent --min-agents 20 --min-skills 37</code></li><li><code>python skills/codex-workflows/scripts/check_codex_native_rules.py --native-root skills/codex-workflows/templates/codex-native/.agent</code></li></ul><ol start="4"><li>Run tests and validation:</li></ol><ul><li><code>python -m unittest discover -s tests -p &quot;test_*.py&quot;</code></li><li><code>node tests/test_cw_cli_node.js</code></li><li><code>python scripts/ci_validate_skill.py --skills-root skills</code></li><li><code>npx @codex-workflow/cw --dry-run</code></li><li><code>cd website &amp;&amp; npm run docs:build</code></li></ul><ol start="5"><li>Run stack packs when applicable:</li></ol><ul><li>Node: <code>python skills/codex-node-validation-pack/scripts/validate_node_stack.py --project .</code></li><li>Python: <code>python skills/codex-python-validation-pack/scripts/validate_python_stack.py --project .</code></li><li>Rust: <code>python skills/codex-rust-validation-pack/scripts/validate_rust_stack.py --project .</code></li></ul><ol start="6"><li>Release with automation:</li></ol><ul><li>Dry run: <code>python scripts/release_automation.py --version 1.1.0</code></li><li>Apply + commit + tag + push: <code>python scripts/release_automation.py --version 1.1.0 --apply --commit --tag --push</code></li></ul><ol start="7"><li>CI E2E verification for installer:</li></ol><ul><li><code>.github/workflows/ci.yml</code> job <code>cw-install-e2e-matrix</code> validates <code>npx @codex-workflow/cw</code> on <code>ubuntu-latest</code>, <code>macos-latest</code>, and <code>windows-latest</code>.</li></ul>',53)])])}const w=e(i,[["render",s]]);export{u as __pageData,w as default};
